ORDER = ['01-intro', '02-setup', '03-patients', '04-care', '10-journey',
         '11-corrections', '05-billing', '06-hr', '07-reports', '09-extra',
         '12-parent', '13-roles', '08-close']
SCRIPTS.sort(key=lambda item: ORDER.index(item[0]))

def seconds(p):
    output=subprocess.run([FF,'-i',str(p)],capture_output=True,text=True).stderr
    m=re.search(r'Duration: (\d+):(\d+):(\d+\.\d+)',output)
    if not m: raise RuntimeError('duration not found '+str(p))
    return int(m[1])*3600+int(m[2])*60+float(m[3])
def timestamp(t):
    ms=round(t*1000); h=ms//3600000; m=ms//60000%60; s=ms//1000%60
    return f'{h:02}:{m:02}:{s:02},{ms%1000:03}'

def wrap(text):
    words=text.split(); lines=['']
    for word in words:
        if len(lines[-1])+len(word)+1>51 and lines[-1]: lines.append(word)
        else: lines[-1]=(lines[-1]+' '+word).strip()
    return '\n'.join(lines)

out=[]; offset=0; i=1
for key, script in SCRIPTS:
    duration=seconds(B/(key+'.mp4')); phrases=script.split('|'); total=sum(len(s) for s in phrases)
    start=offset
    for phrase in phrases:
        end=start+duration*len(phrase)/total
        out.append(f'{i}\n{timestamp(start)} --> {timestamp(end)}\n{wrap(phrase)}\n\n')
        i+=1; start=end
    offset+=duration
srt=B/'clinic-full-training.hi.srt'; srt.write_text(''.join(out),encoding='utf-8')
source=B/'clinic-full-training.mp4'; tmp=B/'clinic-subtitled-temp.mp4'
subprocess.run([FF,'-y','-v','error','-i',str(source),'-i',str(srt),'-map','0:v','-map','0:a','-map','1:0','-c:v','copy','-c:a','copy','-c:s','mov_text','-metadata:s:s:0','language=hin','-movflags','+faststart',str(tmp)],check=True)
tmp.replace(source)
print('Created approximate subtitle track and sidecar:', srt)
